before.content:
    handshake.destroy()
    channel?.destroy()
    if (socket.readyState === WebSocket.OPEN) {
      socket.send(relayEnvelope(connectionId, route, FrameType.CLOSE, 0, 0, new Uint8Array([1])))
      socket.close(1000, "client closed")
    } else if (socket.readyState === WebSocket.CONNECTING) socket.close(1000, "client closed")
  },
}

after.content:
  close: () => {
    if (closed) return
    closed = true
    socket.onopen = null
    socket.onmessage = null
    socket.onerror = null
    socket.onclose = null
    handshake.destroy()
    channel?.destroy()
    if (socket.readyState === WebSocket.OPEN || socket.readyState === WebSocket.CONNECTING) {
      socket.close(1000, "client closed")
    }
  },
}
